import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.CZGNF-7T.js";const u=JSON.parse('{"title":"기안서 작성 및 상신","description":"","frontmatter":{},"headers":[],"relativePath":"approval/draft.md","filePath":"approval/draft.md","lastUpdated":1788103508000}'),o={name:"approval/draft.md"};function d(i,t,n,s,h,c){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="기안서-작성-및-상신" tabindex="-1">기안서 작성 및 상신 <a class="header-anchor" href="#기안서-작성-및-상신" aria-label="Permalink to &quot;기안서 작성 및 상신&quot;">​</a></h1><p>기안자는 회사의 규정과 양식에 따라 문서를 작성하고 결재를 요청(상신)할 수 있습니다.</p><h2 id="_1-기안서-작성-절차" tabindex="-1">1. 기안서 작성 절차 <a class="header-anchor" href="#_1-기안서-작성-절차" aria-label="Permalink to &quot;1. 기안서 작성 절차&quot;">​</a></h2><h3 id="_1단계-기안-보직-선택" tabindex="-1">1단계: 기안 보직 선택 <a class="header-anchor" href="#_1단계-기안-보직-선택" aria-label="Permalink to &quot;1단계: 기안 보직 선택&quot;">​</a></h3><p>기안자가 2개 이상의 부서에 겸직 중인 경우, 이번 결재를 상신할 **기안 보직(소속 부서 및 직책)**을 상단 셀렉트박스에서 선택합니다.</p><ul><li>선택한 기안 보직에 따라 결재선(직속 부서장 및 상위 본부장)과 기안 가능한 문서 양식이 결정됩니다.</li></ul><h3 id="_2단계-문서-유형-양식-선택" tabindex="-1">2단계: 문서 유형(양식) 선택 <a class="header-anchor" href="#_2단계-문서-유형-양식-선택" aria-label="Permalink to &quot;2단계: 문서 유형(양식) 선택&quot;">​</a></h3><p>카테고리별로 분류된 문서 유형 목록에서 작성하고자 하는 양식(예: <code>업무품의서</code>, <code>휴가신청서</code>, <code>지출결의서</code> 등)을 선택합니다.</p><h3 id="_3단계-기본-정보-및-전용-본문-작성" tabindex="-1">3단계: 기본 정보 및 전용 본문 작성 <a class="header-anchor" href="#_3단계-기본-정보-및-전용-본문-작성" aria-label="Permalink to &quot;3단계: 기본 정보 및 전용 본문 작성&quot;">​</a></h3><ul><li><strong>제목</strong>: 결재 문서의 핵심 내용을 직관적으로 입력합니다.</li><li><strong>보안 등급</strong>: <ul><li><code>1등급 (비공개)</code>: 기안자, 결재선 포함자, 지정된 참조자만 열람 가능</li><li><code>2등급 (부서공개)</code>: 기안자 소속 부서원 전체 열람 가능 (기본값)</li><li><code>3등급 (전사공개)</code>: 회사 임직원 전체 열람 가능</li></ul></li><li><strong>양식별 전용 입력 필드</strong>: 각 문서 양식에 맞춘 세부 폼(휴가 기간, 지출 내역 그리드, 계약 금액 등)을 작성합니다.</li></ul><h3 id="_4단계-참조자-공람자-지정-선택" tabindex="-1">4단계: 참조자(공람자) 지정 (선택) <a class="header-anchor" href="#_4단계-참조자-공람자-지정-선택" aria-label="Permalink to &quot;4단계: 참조자(공람자) 지정 (선택)&quot;">​</a></h3><p>결재 진행 및 최종 완료 시 문서를 함께 열람하고 알림을 받아야 하는 임직원을 참조자로 추가할 수 있습니다.</p><h3 id="_5단계-첨부파일-업로드" tabindex="-1">5단계: 첨부파일 업로드 <a class="header-anchor" href="#_5단계-첨부파일-업로드" aria-label="Permalink to &quot;5단계: 첨부파일 업로드&quot;">​</a></h3><p>증빙 서류, 견적서, 계약서 초안 등의 첨부파일을 업로드합니다.</p><h2 id="_2-결재선-실시간-미리보기-preview-route" tabindex="-1">2. 결재선 실시간 미리보기 (Preview Route) <a class="header-anchor" href="#_2-결재선-실시간-미리보기-preview-route" aria-label="Permalink to &quot;2. 결재선 실시간 미리보기 (Preview Route)&quot;">​</a></h2><p>기안서 작성 화면 우측(또는 모바일 하단)에는 입력한 <strong>보직과 금액 정보에 맞춰 실시간으로 계산된 결재선</strong>이 타임라인 형태로 표시됩니다.</p><ul><li>직속 팀장 $\\to$ 상위 본부장 $\\to$ 대표이사 단계가 자동으로 표시됩니다.</li><li>금액 조건부 전결 규정(예: 100만 원 이하 팀장 전결)에 해당하는 경우 결재선이 전결자까지만 축소되어 표시됩니다.</li></ul><h2 id="_3-임시저장과-상신-submit-의-차이" tabindex="-1">3. 임시저장과 상신(Submit)의 차이 <a class="header-anchor" href="#_3-임시저장과-상신-submit-의-차이" aria-label="Permalink to &quot;3. 임시저장과 상신(Submit)의 차이&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">임시저장 (Save Draft)</th><th style="text-align:left;">상신 (Submit)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>문서 상태</strong></td><td style="text-align:left;"><code>임시저장 (draft)</code></td><td style="text-align:left;"><code>결재 진행 중 (pending)</code></td></tr><tr><td style="text-align:left;"><strong>문서 번호</strong></td><td style="text-align:left;">미채번 (null)</td><td style="text-align:left;">미채번 (최종 승인 시 채번)</td></tr><tr><td style="text-align:left;"><strong>타인 열람</strong></td><td style="text-align:left;">기안자 본인만 열람 및 수정/삭제 가능</td><td style="text-align:left;">1단계 결재자 및 결재선 참여자 열람 가능</td></tr><tr><td style="text-align:left;"><strong>결재선 생성</strong></td><td style="text-align:left;">결재선 생성되지 않음</td><td style="text-align:left;">조직도 기반 결재선이 확정 복사됨</td></tr><tr><td style="text-align:left;"><strong>알림 발송</strong></td><td style="text-align:left;">발송되지 않음</td><td style="text-align:left;">1단계 결재자에게 모바일 푸시 및 웹 알림 발송</td></tr></tbody></table>',19)])])}const g=e(o,[["render",d]]);export{u as __pageData,g as default};
